        Map<net.minecraft.world.level.block.state.properties.Property<?>,Comparable<?>> values=new HashMap<>();values.put(property,7);List<String> propertyErrors=new ArrayList<>();check(RuntimeModelObservation.stateProperties(values,propertyErrors).get("named").getAsString().equals("named_7"),"Property.getName differs from toString");
        var emptyProperty=new net.minecraft.world.level.block.state.properties.Property<Integer>("empty",Integer.class){public Collection<Integer> getPossibleValues(){return List.of(7);}public String getName(Integer value){return "";}public Optional<Integer> getValue(String value){return Optional.of(7);}};values.put(emptyProperty,7);check(!RuntimeModelObservation.stateProperties(values,propertyErrors).has("empty")&&propertyErrors.contains("state_property_limit"),"actual empty property omitted");
