        check(observation.get("origin").getAsString().equals("test_fixture"),"fixture origin");check(observation.get("status").getAsString().equals("complete"),"item complete");check(observation.getAsJsonArray("models").size()==3,"replacement handles");check(observation.getAsJsonArray("queries").size()==14&&observation.getAsJsonArray("quads").size()==14,"duplicate type occurrences seven buckets");
