        Fixture block=new Fixture(blockSource.manifest().getAsJsonObject("selected_owner"));byte[] blockBytes=RuntimeModelObservation.fixture(block);check(parsed(blockBytes).get("status").getAsString().equals("complete"),"block complete");check(block.calls.contains("block5:null"),"block distinct query callback");
